          "answer_quote": "Ambessa is a fighter and assassin",
          "covered": true,
          "mechanic_id": "overview_role",
          "reason": "Matches the supplied role tags."
        },
        {
          "answer_quote": "combines physical ability damage with empowered attacks that restore energy",
          "covered": true,
          "mechanic_id": "overview_damage",
          "reason": "Explains both physical ability damage and the attack-based energy cycle."
        },
        {
          "answer_quote": "Her ability-linked dashes let her reposition, but cannot cross terrain or occur while immobilized or grounded. Her ultimate blinks her to the farthest enemy champion in a chosen line.",
          "covered": true,
          "mechanic_id": "overview_mobility",
          "reason": "Explains dash access, limitations, and ultimate targeting."
        }
